508		mustHandoff(t, s, "R2", "站点A", "站点C", []string{"P001", "P002"}, tClock(2026, 10, 5, 13, 0))
509		replay, replayed2, err := s.Return("RT1", "R1", "错发站点", tClock(2026, 10, 5, 14, 0))
510		if err != nil || !replayed2 || replay != first {
511			t.Fatalf("包裹再交接后重放仍须返回首次结果: err=%v replayed=%v", err, replayed2)
512		}
513		for _, id := range []string{"P001", "P002"} {
514			p, _ := s.Query(id)
515			if p.Station != "站点C" || len(p.Trail) != 4 {
516				t.Fatalf("重放不得追加轨迹或改变站点，%s: station=%q trail=%d", id, p.Station, len(p.Trail))
517			}
518		}
519	
520		// 同一退回请求号换原交接或原因：冲突。
521		mustHandoff(t, s, "R9", "站点C", "站点A", []string{"P001"}, tClock(2026, 10, 5, 15, 0))
522		if _, _, err := s.Return("RT1", "R9", "错发站点", tClock(2026, 10, 5, 16, 0)); err == nil {
523			t.Fatal("换原交接必须报冲突")
524		}
525		if _, _, err := s.Return("RT1", "R1", "别的原因", tClock(2026, 10, 5, 16, 0)); err == nil {
526			t.Fatal("换原因必须报冲突")
527		}
528		saved := s.data.Returns["RT1"]
529		if saved != first || saved.Handoff != "R1" || saved.Reason != "错发站点" {
530			t.Fatalf("冲突提交不得改动已有退回结果: %+v", saved)
531		}
532	}
