		p, _ := s.Query(id)
		if p.Station != "站点A" || p.Status != statusDelivering {
			t.Fatalf("%s 出站后应仍记出发站且配送中: %+v", id, p)
		}
		if len(p.Trail) != 2 {
			t.Fatalf("%s 应有两条轨迹，得到 %d", id, len(p.Trail))
		}
		e := p.Trail[1]
		if e.Op != "出站" || e.Station != "站点A" || e.Batch != "B1" || e.Courier != "张三" || !e.Time.Equal(t2) {
			t.Fatalf("%s 出站记录不符: %+v", id, e)
		}
	}
}

