// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执）。
// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
func lastFlowEvent(trail []Event) Event {
	for i := len(trail) - 1; i >= 0; i-- {
		switch trail[i].Op {
		case "冻结", "解除冻结":
			continue
		default:
			return trail[i]
		}
	}
	return Event{}
}

