		t.Fatalf("冲突提交不得改动已有冻结结果: %+v", saved)
	}

	// 解除后同号同内容仍重放首次结果，不检查当前状态、不再次冻结。
	if _, _, err := s.Unfreeze("U1", "E1", "核实放行", tClock(2026, 10, 5, 12, 0)); err != nil {
