		t.Fatal("异常单不存在时解除必须失败")
	}
	// 首次解除成功。
	if _, _, err := s.Unfreeze("U1", "E1", "放行", tClock(2026, 10, 5, 11, 0)); err != nil {
		t.Fatal(err)
	}
	// 异常单已解除：再次解除拒绝（即便使用新请求号）。
	if _, _, err := s.Unfreeze("U2", "E1", "再处理", tClock(2026, 10, 5, 11, 30)); err == nil {
		t.Fatal("已解除的异常单不能重复解除")
	}
