	runCLI(t, dbPath, "register", "--id", "X", "--station", "站点A")
	runCLI(t, dbPath, "handoff", "--request", "X", "--from", "站点A", "--to", "站点B", "--parcel", "X")
	// 异常单号、解除请求号均与包裹号/交接请求号同名。
